---MODEL
export const POWER_CLASSES = ['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced'] as const;
export type PowerClass = (typeof POWER_CLASSES)[number];

export const HERO_STATUSES = ['Active', 'Injured', 'Reserve', 'MIA'] as const;
export type HeroStatus = (typeof HERO_STATUSES)[number];

export const CLEARANCE_TIERS = ['Tier 1', 'Tier 2', 'Tier 3', 'Tier 4', 'Tier 5'] as const;
export type ClearanceTier = (typeof CLEARANCE_TIERS)[number];

export interface Hero {
  /** Roster id, e.g. `HRO-0007`. Never edited. */
  readonly id: string;
  /** Public-facing hero name. */
  readonly name: string;
  /** Civilian identity. `Unknown` or `Classified` where the record is restricted. */
  readonly alias: string;
  readonly powerClass: PowerClass;
  /** Power index, 0-100. */
  readonly power: number;
  readonly status: HeroStatus;
  readonly clearance: ClearanceTier;
  readonly missions: number;
  /** Percentage of missions completed successfully, 0-100. */
  readonly successRate: number;
  /** Free-text dossier shown on the detail screen. */
  readonly dossier: string;
}
---SERVICE
import { Service, signal } from '@angular/core';
import { EXAMPLE_HEROES } from './hero.example-data';
import type { Hero } from './hero.model';

/** The editable fields of a hero. The id is fixed once the record exists. */
export type HeroChanges = Partial<Omit<Hero, 'id'>>;

/**
 * Holds the hero roster as in-memory signal state. There is no backend: the roster is
 * seeded from `EXAMPLE_HEROES` (example data) and resets on every page load.
 */
@Service()
export class HeroService {
  private readonly roster = signal<readonly Hero[]>(EXAMPLE_HEROES);

  /** The whole roster, read-only. Derive views from it with `computed()` in a ViewModel. */
  readonly heroes = this.roster.asReadonly();

  /** Look up one hero by roster id. Returns `undefined` when no hero has that id. */
  byId(id: string): Hero | undefined {
    return this.roster().find((hero) => hero.id === id);
  }

  /** Apply `changes` to the hero with `id`. Unknown ids are a no-op. */
  update(id: string, changes: HeroChanges): void {
    this.roster.update((heroes) => heroes.map((hero) => (hero.id === id ? { ...hero, ...changes } : hero)));
  }
}
