<div hlmSidebarWrapper>
  <hlm-sidebar>
    <div hlmSidebarHeader>
      <div class="flex items-center gap-2 px-2 py-1">
        <ng-icon name="lucideRadar" class="text-sidebar-primary" />
        <span class="truncate font-semibold">Hero Ops Console</span>
      </div>
    </div>

    <div hlmSidebarContent>
      <nav aria-label="Main">
        <ul hlmSidebarMenu>
          @for (destination of vm.destinations; track destination.path) {
            <li hlmSidebarMenuItem>
              <a
                hlmSidebarMenuButton
                [routerLink]="['/', destination.path]"
                routerLinkActive
                #active="routerLinkActive"
                [isActive]="active.isActive"
              >
                <ng-icon [name]="destination.icon" />
                <span>{{ destination.label }}</span>
              </a>
            </li>
          }
        </ul>
      </nav>
    </div>

    <div hlmSidebarFooter>
      <p class="truncate px-2 py-1 text-sm text-sidebar-muted">Operations desk</p>
    </div>
  </hlm-sidebar>

  <main hlmSidebarInset>
    <header class="flex flex-wrap items-center gap-2 border-b border-border px-4 py-3 md:px-6">
      <button hlmSidebarTrigger></button>

      <nav aria-label="Breadcrumb" class="min-w-0 flex-1">
        <ol class="flex min-w-0 items-center gap-2 text-sm">
          <li class="truncate text-muted-foreground">Hero Ops Console</li>
          <li aria-hidden="true" class="text-muted-foreground">/</li>
          <li aria-current="page" class="truncate font-medium">{{ vm.currentPage() }}</li>
        </ol>
      </nav>

      <div class="order-last basis-full sm:order-none sm:basis-64">
        <input hlmInput type="search" aria-label="Search heroes" placeholder="Search heroes" />
      </div>

      <div class="flex items-center gap-1">
        <button
          hlmBtn
          variant="ghost"
          size="icon"
          aria-label="Notifications"
          hlmTooltip="Notifications"
        >
          <ng-icon name="lucideBell" />
        </button>

        <button
          hlmBtn
          variant="ghost"
          size="icon"
          [attr.aria-label]="vm.isDark() ? 'Switch to light theme' : 'Switch to dark theme'"
          [hlmTooltip]="vm.isDark() ? 'Switch to light theme' : 'Switch to dark theme'"
          (click)="vm.toggleTheme()"
        >
          <ng-icon [name]="vm.isDark() ? 'lucideSun' : 'lucideMoon'" />
        </button>

        <hlm-avatar role="img" aria-label="Signed in as the duty commander">
          <span hlmAvatarFallback>DC</span>
        </hlm-avatar>
      </div>
    </header>

    <div class="flex min-w-0 flex-1 flex-col p-4 md:p-6">
      <router-outlet />
    </div>
  </main>
</div>
---CARD
import { Component, computed, input } from '@angular/core';
import { RouterLink } from '@angular/router';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmBadgeImports } from '@spartan-ng/helm/badge';
import { HlmCardImports } from '@spartan-ng/helm/card';
import type { Hero, HeroStatus } from '../domain/hero.model';
import { PowerMeter } from './power-meter';

const STATUS_VARIANT: Readonly<Record<HeroStatus, 'default' | 'secondary' | 'outline' | 'destructive'>> = {
  Active: 'default',
  Reserve: 'secondary',
  Injured: 'outline',
  MIA: 'destructive',
};

/** One hero as a card. Presentational: takes the record as an input and injects nothing. */
@Component({
  selector: 'app-hero-card',
  imports: [RouterLink, HlmAvatarImports, HlmBadgeImports, HlmCardImports, PowerMeter],
  template: `
    <div hlmCard class="h-full">
      <div hlmCardHeader class="flex flex-row items-center gap-3">
        <hlm-avatar aria-hidden="true">
          <span hlmAvatarFallback>{{ initials() }}</span>
        </hlm-avatar>
        <div class="flex min-w-0 flex-col">
          <h3 hlmCardTitle class="truncate">
            <a class="rounded-sm underline-offset-4 hover:underline" [routerLink]="['/detail', hero().id]">{{ hero().name }}</a>
          </h3>
          <p hlmCardDescription class="truncate">{{ hero().alias }}</p>
        </div>
      </div>
      <div hlmCardContent class="flex flex-col gap-3">
        <div class="flex flex-wrap gap-1">
          <span hlmBadge variant="secondary">{{ hero().powerClass }}</span>
          <span hlmBadge [variant]="statusVariant()">{{ hero().status }}</span>
        </div>
        <app-power-meter [value]="hero().power" />
        <p class="text-xs text-muted-foreground">
          {{ hero().missions }} missions · {{ hero().successRate }}% success
        </p>
      </div>
    </div>
  `,
})
export class HeroCard {
  readonly hero = input.required<Hero>();

  protected readonly statusVariant = computed(() => STATUS_VARIANT[this.hero().status]);

  /** Two-letter portrait fallback from the public name, e.g. `Dr. Ion` -> `DI`. */
  protected readonly initials = computed(() =>
    this.hero()
      .name.replace(/[^A-Za-z\s]/g, '')
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((word) => word[0].toUpperCase())
      .join(''),
  );
}
