        role="meter"
        aria-label="Power"
        aria-valuemin="0"
        aria-valuemax="100"
        [attr.aria-valuenow]="value()"
        class="h-2 w-full overflow-hidden rounded-full bg-muted"
      >
        <div class="h-full rounded-full bg-primary" [style.width.%]="value()"></div>
      </div>
    </div>
  `,
})
export class PowerMeter {
  readonly value = input.required<number>();
}
