import type { HeroStatus } from '../domain/hero.model';

export type HeroStatusVariant = 'default' | 'secondary' | 'outline' | 'destructive';

/** Badge variant per hero status. Shared by every screen that shows a status pill. */
export const HERO_STATUS_VARIANT: Readonly<Record<HeroStatus, HeroStatusVariant>> = {
  Active: 'default',
  Reserve: 'secondary',
  Injured: 'outline',
  MIA: 'destructive',
};

/** Two-letter portrait fallback from the public name, e.g. `Dr. Ion` -> `DI`. */
export function heroInitials(name: string): string {
  return name
    .replace(/[^A-Za-z\s]/g, '')
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((word) => word[0].toUpperCase())
    .join('');
}
EOF
cat > src/app/heroes/heroes.view-model.ts <<'EOF'
import { computed, inject, Injectable, signal } from '@angular/core';
import { HeroService } from '../domain/hero.service';
import { POWER_CLASSES, type Hero, type PowerClass } from '../domain/hero.model';
import { HERO_STATUS_VARIANT, heroInitials, type HeroStatusVariant } from '../ui/hero-presentation';

export const ALL_CLASSES = 'All classes';
export type ClassFilter = PowerClass | typeof ALL_CLASSES;

/** One roster line with its presentation already derived, so the template reads it straight off. */
export interface RosterRow {
  readonly hero: Hero;
  readonly initials: string;
  readonly statusVariant: HeroStatusVariant;
}

function isClassFilter(value: unknown): value is ClassFilter {
  return value === ALL_CLASSES || (POWER_CLASSES as readonly unknown[]).includes(value);
}

// Component-scoped: provided by Heroes, so each visit starts with an empty filter.
@Injectable()
export class HeroesViewModel {
  private readonly heroService = inject(HeroService);

  readonly classOptions: readonly ClassFilter[] = [ALL_CLASSES, ...POWER_CLASSES];

  private readonly query = signal('');
  readonly classFilter = signal<ClassFilter>(ALL_CLASSES);

  readonly totalCount = computed(() => this.heroService.heroes().length);

  /** Filtered by class and by a case-insensitive match on name, alias, or roster id; highest power first. */
  readonly rows = computed<readonly RosterRow[]>(() => {
    const query = this.query().trim().toLowerCase();
    const powerClass = this.classFilter();

    return this.heroService
      .heroes()
      .filter((hero) => powerClass === ALL_CLASSES || hero.powerClass === powerClass)
      .filter((hero) => query === '' || [hero.name, hero.alias, hero.id].some((field) => field.toLowerCase().includes(query)))
      .sort((a, b) => b.power - a.power)
      .map((hero) => ({
        hero,
        initials: heroInitials(hero.name),
        statusVariant: HERO_STATUS_VARIANT[hero.status],
      }));
  });

  readonly visibleCount = computed(() => this.rows().length);

  setQuery(value: string): void {
    this.query.set(value);
  }

  /** The select emits its value untyped, so anything outside the known filters is ignored. */
  setClassFilter(value: unknown): void {
    if (isClassFilter(value)) this.classFilter.set(value);
  }
}
EOF
